from bisect import bisect_left

def count_rectangles(rectangles, points):
    by_height = {}
    for length, height in rectangles:
        by_height.setdefault(height, []).append(length)
    for arr in by_height.values():
        arr.sort()                                   # sort once per height group

    result = []
    for x, y in points:
        count = 0
        for h in range(y, 101):                       # small, fixed height range
            if h in by_height:
                arr = by_height[h]
                idx = bisect_left(arr, x)               # binary search for length >= x
                count += len(arr) - idx
        result.append(count)
    return result

