import java.util.*;

public class Main {
    static int[] countRectangles(int[][] rectangles, int[][] points) {
        Map<Integer, List<Integer>> byHeight = new HashMap<>();
        for (int[] rect : rectangles) {
            byHeight.computeIfAbsent(rect[1], k -> new ArrayList<>()).add(rect[0]);
        }
        for (List<Integer> list : byHeight.values()) Collections.sort(list);  // sort once per height group

        int[] result = new int[points.length];
        for (int p = 0; p < points.length; p++) {
            int x = points[p][0], y = points[p][1], count = 0;
            for (int h = y; h <= 100; h++) {                    // small, fixed height range
                List<Integer> arr = byHeight.get(h);
                if (arr != null) {
                    int idx = Collections.binarySearch(arr, x);
                    if (idx < 0) idx = -idx - 1;
                    count += arr.size() - idx;                    // binary search for length >= x
                }
            }
            result[p] = count;
        }
        return result;
    }
}

