#include <bits/stdc++.h>
using namespace std;

vector<int> countRectangles(vector<vector<int>>& rectangles, vector<vector<int>>& points) {
    unordered_map<int, vector<int>> byHeight;
    for (auto& rect : rectangles) byHeight[rect[1]].push_back(rect[0]);
    for (auto& [h, arr] : byHeight) sort(arr.begin(), arr.end());    // sort once per height group

    vector<int> result;
    for (auto& pt : points) {
        int x = pt[0], y = pt[1], count = 0;
        for (int h = y; h <= 100; h++) {                              // small, fixed height range
            auto it = byHeight.find(h);
            if (it != byHeight.end()) {
                auto& arr = it->second;
                int idx = lower_bound(arr.begin(), arr.end(), x) - arr.begin();  // binary search for length >= x
                count += arr.size() - idx;
            }
        }
        result.push_back(count);
    }
    return result;
}
